args<-commandArgs(trailingOnly=TRUE);if(length(args)!=2)stop('usage: Rscript adapters/descore-to-table.R DEscore.csv output.csv')
d<-read.csv(args[1],check.names=FALSE,fileEncoding='UTF-8');map<-c(pathway_id='ID',description='Description',group='group',celltype='celltype',qvalue='qvalue',up_count='upCount',down_count='downCount',all_count='allCount',de_score='DE.score');if(!all(map %in% names(d)))stop('source DEscore fields are missing');out<-d[unname(map)];names(out)<-names(map);write.csv(out,args[2],row.names=FALSE,fileEncoding='UTF-8');cat('Converted supplied DEscore rows: ',nrow(out),'\n',sep='')
